package com.mahesh.empleave.common.dto;import com.mahesh.empleave.audit.*;import com.mahesh.empleave.leave.*;import com.mahesh.empleave.leavebalance.*;import com.mahesh.empleave.user.*;import java.math.*;import java.time.*;public final class ApiDtos{private ApiDtos(){}public record Employee(Long id,String email,String fullName,Role role,Long departmentId,Long managerId){}public record Department(Long id,String name,String code){}public record LeaveType(Long id,String name,boolean active){}public record Leave(Long id,Long applicantId,String applicantName,String leaveType,LocalDate startDate,LocalDate endDate,int workingDays,LeaveStatus status,String reason,String reviewerNote){}public record Balance(Long id,Long leaveTypeId,String leaveType,BigDecimal remainingDays){}public record BalanceTxn(Long id,Long applicationId,BigDecimal delta,LocalDateTime createdAt){}public record Holiday(Long id,LocalDate date,String name){}public record Notification(Long id,String message,LocalDateTime createdAt,LocalDateTime readAt){}public record Audit(Long id,Long actorId,String action,String entityType,Long entityId,LocalDateTime createdAt){}public static Employee employee(AppUser u){return new Employee(u.getId(),u.getEmail(),u.getFullName(),u.getRole(),u.getDepartment()==null?null:u.getDepartment().getId(),u.getManager()==null?null:u.getManager().getId());}public static Department department(com.mahesh.empleave.department.Department x){return new Department(x.getId(),x.getName(),x.getCode());}public static LeaveType leaveType(com.mahesh.empleave.leavetype.LeaveType x){return new LeaveType(x.getId(),x.getName(),x.isActive());}public static Leave leave(LeaveApplication x){return new Leave(x.getId(),x.getApplicant().getId(),x.getApplicant().getFullName(),x.getLeaveType(),x.getStartDate(),x.getEndDate(),x.getWorkingDays(),x.getStatus(),x.getReason(),x.getReviewerNote());}public static Balance balance(LeaveBalance x){return new Balance(x.getId(),x.getLeaveType().getId(),x.getLeaveType().getName(),x.getRemainingDays());}public static BalanceTxn transaction(BalanceTransaction x){return new BalanceTxn(x.getId(),x.getApplication()==null?null:x.getApplication().getId(),x.getDelta(),x.getCreatedAt());}public static Holiday holiday(com.mahesh.empleave.holiday.Holiday x){return new Holiday(x.getId(),x.getHolidayDate(),x.getName());}public static Notification notification(com.mahesh.empleave.notification.Notification x){return new Notification(x.getId(),x.getMessage(),x.getCreatedAt(),x.getReadAt());}public static Audit audit(AuditLog x){return new Audit(x.getId(),x.getActor()==null?null:x.getActor().getId(),x.getAction(),x.getEntityType(),x.getEntityId(),x.getCreatedAt());}}
